import math
from sympy import primerange, mobius
from fractions import Fraction
N=3000
sq=[0]*(N+1)
for n in range(1,N+1):
    sq[n]=all(n%(p*p) for p in primerange(2,int(n**.5)+1))
P=list(primerange(2,200000))
def eta(t):
    r=1.0
    for p in P:
        if t%p==0: r/= (p*p-2)
        if p>t: break
    return r
A0=1.0
for p in P: A0*=1-2/p**2
def sqf(t): return all(t%(p*p) for p in primerange(2,int(t**.5)+1)) 
T=3000
et=[0]+[eta(t) if sqf(t) else 0 for t in range(1,T)]
def g(q,l):
    s=0
    for d in range(1,4000):
        mu=int(mobius(d))
        if mu==0: continue
        gg=math.gcd(d*d,q)
        if l%gg==0: s+=mu*gg/(d*d*q)
    return s
B=lambda u:(u%1)*(1-u%1)
def test(x,q):
    Q=[0]*(q+1); 
    for n in range(1,x+1):
        if sq[n]: Q[n%q or q]+=1
    gs=[g(q,l) for l in range(1,q+1)]
    E=[Q[l]-gs[l-1]*x for l in range(1,q+1)]
    V=sum(e*e for e in E)
    def A(m): return A0*sum(et[t] for t in range(1,T) if m%(t*t)==0)
    def C(m): return sum(1 for n in range(1,x-m+1) if sq[n] and sq[n+m])
    S=sum(C(h*q)-A(h*q)*(x-h*q) for h in range(1,x//q+1))
    MT=0
    for t in range(1,T):
        if et[t]:
            m=t*t//math.gcd(t*t,q); MT+=et[t]*m*B(x/(q*m))
    MT*=A0*q
    Qx=sum(sq[1:x+1])
    rhs=MT+2*S+Qx-6*x/math.pi**2-2*x*sum(a*b for a,b in zip(gs,E))
    print(x,q,V,rhs)
test(200,7);test(300,12);test(150,1);test(100,30)
E
